import { useEffect, useState } from 'react';

type User = { id: number; name: string };

export function UserList({ teamId }: { teamId: number }) {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);
  const options = { headers: { 'X-Team': String(teamId) } };

  useEffect(() => {
    setLoading(true);
    fetch(`/api/teams/${teamId}/users`, options)
      .then((r) => r.json())
      .then((data) => {
        setUsers(data);
        setLoading(false);
      });
  }, [teamId, options]);

  if (loading) return <p>Loading...</p>;
  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
}
