Our Node service's memory grows until it gets OOM-killed after about two days. Heap snapshot shows hundreds of thousands of closures retained by an EventEmitter. I think it's this module:

```js
const EventEmitter = require('events');
const bus = new EventEmitter();
bus.setMaxListeners(0);

class Session {
  constructor(socket, userId) {
    this.socket = socket;
    this.userId = userId;
    this.buffer = [];
    bus.on('broadcast', (msg) => {
      if (msg.audience === 'all' || msg.audience === this.userId) {
        this.buffer.push(msg);
        this.flush();
      }
    });
    socket.on('close', () => {
      this.closed = true;
    });
  }

  flush() {
    if (this.closed) return;
    while (this.buffer.length) {
      this.socket.send(JSON.stringify(this.buffer.shift()));
    }
  }
}

module.exports = { bus, Session };
```

